import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


def parse_ip_state(value):
    """

    :param value:
    :return:
    """
    return re.sub(r'\s\[\w+\]', '', value)


class UeDispFailure(Exception):
    """
    Exception class for ue_disp
    """
    pass


class UeDisp(EgateCommandBase):
    """
    Parser for ue_disp command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(UeDisp, self).__init__()
        self.command = 'ue_disp'
        self.params = params
        self.executed_phrase = r'.*?(Configured|UE\-\d+).*?EGATE>'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute_and_parse(self, egate_id=0):
        """Execute egate cmd and parse it"""
        status, output = self.execute(egate_id=0, command=self.to_execute)
        if status:
            parsed_output = self._parse_ue_disp_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise UeDispFailure(output)

    def _build_command(self):
        """
        Build ue_stats command.
        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    def _parse_ue_disp_output(self, output):
        try:
            ue_id = str(self.params['id'])
        except KeyError:
            return self._parse_without_id(output)

        if '-' in ue_id:
            return self._parse_without_id(output)
        if 'at' not in list(self.params.keys()):
            return self._parse_with_id(output)
        else:
            return self._parse_with_id_at_ue(output)

    def _parse_without_id(self, cmd_output):
        """
        Parse ue_disp command output

        :param cmd_output: output received from execution of ue_disp command
        :return: dict with information about UEs with Id as main key
        e.g.:
        {
        ... '1': {'Group': '-',
        ...       'IP addresses': '1.2.3.4* (PDN1)',
        ...       'Location': '1.11',
        ...       'MME': '1',
        ...       'NAT IP addresses': '1.2.33.6 (PDN1)',
        ...       'State': 'IDLE',
        ...       'Type': 'INT',
        ...       'UE Id': '1',
        ...       'UEC': '1'},
        ... '2': {'Group': '-',
        ...       'IP addresses': '<inactive>',
        ...       'Location': '1.11',
        ...       'MME': '1',
        ...       'NAT IP addresses': '<inactive>',
        ...       'State': 'OFF',
        ...       'Type': 'INT',
        ...       'UE Id': '2',
        ...       'UEC': '1'}
        }
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='UE Id', list_of_output_parsed_lines=output)

    def _parse_with_id(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        cmd_parser.parse_column_value_with_custom_function('Parameter', parse_ip_state)
        cmd_parser.remove_row_with_value_in_column('Parameter', 'Cell')
        cmd_parser.remove_row_with_value_in_column('Parameter', 'Security')
        cmd_parser.remove_row_with_value_in_column('Parameter', 'PDN')
        output = cmd_parser.get_list_of_output_parsed_lines()
        output = self._skip_pdn_info(output)
        return create_dict_with_key(key='Parameter', list_of_output_parsed_lines=output)

    def _parse_with_id_at_ue(self, cmd_output):
        """

        :param cmd_output:
        :return:
        """
        result = re.search(r'(^UE\-\d+.*\s+)(\={3,})([\s\S]*?)(\={3,})', cmd_output, re.MULTILINE)
        if result:
            cmd_output = result.group(0)

        cmd_parser = EgateDispCommandsOutputParser(cmd_output)
        output = cmd_parser.get_list_of_output_parsed_lines()
        output = self._parse_configured_scells(output)
        return create_dict_with_key(key='Parameter', list_of_output_parsed_lines=output)

    def _parse_configured_scells(self, list_of_output_parsed_lines):
        """

        :param list_of_output_parsed_lines:
        :return:
        """
        new_list = []
        for idx, line in enumerate(list_of_output_parsed_lines):
            if "SCell/eNB Id" in line[0]:
                scell_info = dict()
                scell_id, enb_id, cell_id = re.findall(r'(\d+)\/(\d+)\:(\d+)', line[1])[0]

                scell_info["eNB Id"] = enb_id
                scell_info["Cell Id"] = cell_id
                scell_info["SCell state"] = list_of_output_parsed_lines[idx + 1][1]
                scell_info["Used band"] = list_of_output_parsed_lines[idx + 2][1]
                scell_info["Band type"] = re.findall(r'(?<=\().+?(?=\))', list_of_output_parsed_lines[idx + 2][0])[0]
                scell_info["DL E-ARFCN"] = list_of_output_parsed_lines[idx + 3][1]

                new_list.append(["SCell-{}".format(scell_id), scell_info])

            elif "SCell state" in line[0]:
                continue
            elif "Used band" in line[0]:
                continue
            elif "DL E-ARFCN" in line[0]:
                continue
            else:
                new_list.append(line)
        return new_list

    def _skip_pdn_info(self, parsed_lines):
        """

        :param parsed_lines:
        :return:
        """
        pdn_line_idx = self._find_pdn_line_start_index(parsed_lines)
        if pdn_line_idx:
            parsed_output = parsed_lines[0:pdn_line_idx[0][1]]
            return parsed_output
        else:
            return parsed_lines

    def _find_pdn_line_start_index(self, parsed_lines):
        """

        :param parsed_lines:
        :return:
        """
        pdn_line_idx = []
        for line_idx, line in enumerate(parsed_lines):
            if re.search(r'PDN\s\d+', line[0]):
                pdn_line_idx.append((line[0], line_idx))
        return pdn_line_idx
